import React, { useEffect, useState } from "react";
import { BrowserRouter as Router, Routes, Route, Outlet, useLocation } from "react-router-dom";
import { Navigation } from "./components/navigation";
import { Header } from "./components/header";
import { About } from "./components/about";
import { About2 } from "./components/about2";
import { Features } from "./components/features";
import Login from "./components/login";
import Register from "./components/register";
import JsonData from "./data/data.json";
import SmoothScroll from "smooth-scroll";
import "./App.css";
import ProfilePage from "./components/profile";
import Footer from "./components/footer";
import LandingPage from "./components/landing"; 
import Findavet from "./components/findavet";
import Shops from "./components/shops";
import PetShop from "./components/petshop";
import ShopProfile from "./components/shopprofile";
import OtpPage from "./components/otppage";
import VetLayout from "./components/VetLayout";
import VetDashboard from "./components/VetDashboard";
import VetAppointments from "./components/VetAppointments";
import VetHistory from "./components/VetHistory";

export const scroll = new SmoothScroll('a[href*="#"]', {
  speed: 1000,
  speedAsDuration: true,
});

// Layout component to wrap Navigation with pages
const Layout = ({ isLoggedIn, setIsLoggedIn }) => {
  return (
    <>
      <Navigation isLoggedIn={isLoggedIn} setIsLoggedIn={setIsLoggedIn} />
      <Outlet /> {/* Renders the matched child route */}
    </>
  );
};

const App = () => {
  const [landingPageData, setLandingPageData] = useState({});
  const [isLoggedIn, setIsLoggedIn] = useState(false);

  useEffect(() => {
    setLandingPageData(JsonData);
    const token = localStorage.getItem("token");
    setIsLoggedIn(!!token);
  }, []);

  return (
    <Routes>
      {/* Wrap all routes inside Layout */}
      <Route element={<Layout isLoggedIn={isLoggedIn} setIsLoggedIn={setIsLoggedIn} />}>
        <Route path="/" element={<LandingPage />} />
        <Route path="/home" element={
          <>
            <Header data={landingPageData.Header} />
            <Features data={landingPageData.Features} />
            <About data={landingPageData.About} />
            <About2 data={landingPageData.About2} />
            <Footer data={landingPageData.Footer} />
          </>
        }/>
        <Route path="/login" element={<Login setIsLoggedIn={setIsLoggedIn} />} />
        <Route path="/register" element={<Register />} />
        <Route path="/findavet" element={<Findavet />} />
        <Route path="/shops" element={<Shops />} />
        <Route path="/petshop/:clinicId" element={<PetShop />} />
        <Route path="/shopprofile/:clinicId" element={<ShopProfile />} />
        <Route path="/otp" element={<OtpPage />} />
        <Route path="/profile" element={<ProfilePage />} />
      </Route>

      {/* Vet Layout (Separate because it might have different navigation) */}
      <Route path="/clinic/*" element={<VetLayout />}>
        <Route path="dashboard" element={<VetDashboard />} />
        <Route path="appointments" element={<VetAppointments />} />
        <Route path="history" element={<VetHistory />} />
      </Route>
    </Routes>
  );
};

// Wrap App in Router
const AppWrapper = () => (
  <Router>
    <App />
  </Router>
);

export default AppWrapper;
